FUNCTION_BLOCK "{{block_name}}"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT 
      {{cmd_execute}} : Bool;
   END_VAR

   VAR_OUTPUT 
      Done : Bool;
      Busy : Bool;
      Error : Bool;
      Status : Word := 16#7000;
   END_VAR

   VAR 
      statPrevExecute : Bool;
   END_VAR

BEGIN
   IF #{{cmd_execute}} AND NOT #statPrevExecute THEN
      #Done := TRUE;
      #Busy := FALSE;
      #Error := FALSE;
      #Status := 16#0000;
   ELSIF NOT #{{cmd_execute}} THEN
      #Done := FALSE;
      #Busy := FALSE;
      #Status := 16#7000;
   END_IF;
   #statPrevExecute := #{{cmd_execute}};
END_FUNCTION_BLOCK
